<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides payroll compliance rule behavior within the WorkIntel application. */ class PayrollComplianceRule extends Model{protected $fillable=['payroll_compliance_pack_id','code','name','category','calculation_type','basis','rate_percent','employer_rate_percent','fixed_amount','employer_fixed_amount','minimum_basis','maximum_basis','employee_cap','employer_cap','taxable','affects_gross','active','brackets','conditions','priority'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['rate_percent'=>'decimal:4','employer_rate_percent'=>'decimal:4','fixed_amount'=>'decimal:2','employer_fixed_amount'=>'decimal:2','minimum_basis'=>'decimal:2','maximum_basis'=>'decimal:2','employee_cap'=>'decimal:2','employer_cap'=>'decimal:2','taxable'=>'boolean','affects_gross'=>'boolean','active'=>'boolean','brackets'=>'array','conditions'=>'array'];}/** Handles the pack operation for the current WorkIntel workflow. */ public function pack():BelongsTo{return $this->belongsTo(PayrollCompliancePack::class,'payroll_compliance_pack_id');}}
